-- Rewritten to satisfy review criteria.
-- 1. Set timeout settings before any DDL.
SET lock_timeout = '500ms';
SET statement_timeout = '500ms';

-- 2. Add the column.
ALTER TABLE orders ADD COLUMN status text;

-- 3. Add a NOT NULL constraint that will be validated later.
ALTER TABLE orders ADD CONSTRAINT status_not_null CHECK (status IS NOT NULL) NOT VALID;

-- 4. Backfill the column in small batches using a DO block.
DO $$
DECLARE
    last_id bigint := 0;
    rows_updated int := 0;
    max_id bigint;
BEGIN
    LOOP
        WITH upd AS (
            UPDATE orders
            SET status = CASE
                WHEN cancelled_at IS NOT NULL THEN 'cancelled'
                WHEN refunded_cents > 0 AND refunded_cents >= total_cents THEN 'refunded'
                WHEN refunded_cents > 0 THEN 'partly_refunded'
                WHEN shipped_at IS NOT NULL THEN 'shipped'
                ELSE 'placed'
            END
            WHERE status IS NULL AND id > last_id
            ORDER BY id
            LIMIT 5000
            RETURNING id
        )
        SELECT count(*), max(id) INTO rows_updated, max_id FROM upd;
        IF rows_updated = 0 THEN
            EXIT;
        END IF;
        last_id := max_id;
    END LOOP;
END $$;

-- 5. Validate the NOT NULL constraint (uses SHARE UPDATE EXCLUSIVE lock).
ALTER TABLE orders VALIDATE CONSTRAINT status_not_null;

-- 6. Finally set NOT NULL (only a catalog change now).
ALTER TABLE orders ALTER COLUMN status SET NOT NULL;

-- 7. Clean up: drop the temporary constraint.
ALTER TABLE orders DROP CONSTRAINT status_not_null;
